cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 -c "
import yaml,glob
from collections import Counter
live={'ajc-albanese','ajc-fbc','ajc-rr','ajcr-cert-r2','ajcr-charts','ajcr-divrep','ajcr-w5-av'}
c=Counter(); pers=0; fbc=[]
for f in glob.glob('.archon-horizon/inbox/local/items/*.yaml'):
    try: d=yaml.safe_load(open(f))
    except Exception: continue
    if not d or d.get('status')!='open' or d.get('kind')!='memory': continue
    prov=(d.get('metadata') or {}).get('provenance') or {}
    task=prov.get('task','(none)')
    c[task]+=1
    body=(d.get('body') or '')
    if body.strip().startswith('[persistent]'): pers+=1
    if task=='ajc-fbc': fbc.append((d.get('id'), body[:70].replace(chr(10),' ')))
print('open memory total:',sum(c.values()),' of which [persistent]:',pers)
print()
print('by originating lane (LIVE marked *):')
for t,v in c.most_common(): print(f'  {\"*\" if t in live else \" \"} {t:22s} {v}')
print()
print('ajc-fbc own open memory items:')
for i,b in sorted(fbc): print('  ',i,b)
"

cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 -c "
import yaml,glob
live={'ajc-albanese','ajc-fbc','ajc-rr','ajcr-cert-r2','ajcr-charts','ajcr-divrep','ajcr-w5-av'}
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f))
    if d: rows[d['id']]=d
kids={}
for i,d in rows.items():
    p=(d.get('metadata') or {}).get('parent')
    if p: kids.setdefault(p,[]).append(i)
def owner(i): return (rows[i].get('metadata') or {}).get('owner')
def has_live_desc(i,seen=None):
    seen=seen or set()
    if i in seen: return None
    seen.add(i)
    if owner(i) in live: return owner(i)
    for k in kids.get(i,[]):
        r=has_live_desc(k,seen)
        if r: return r
    return None
act=sorted(i for i,d in rows.items() if d.get('status')=='active')
unheld=[]
for i in act:
    o=owner(i); ld=has_live_desc(i)
    tag='LIVE(own)' if o in live else (f'live-desc:{ld}' if ld else '*** NOT HELD ***')
    print(f'  {i:44s} {tag}')
    if o not in live and not ld: unheld.append(i)
print()
print('active but held by NO live lane:',unheld or 'NONE')
"
